sample.code:
#include <iostream>
using namespace std;

int main() {
    int i = 10;
    do {
        cout << "Body ran with i = " << i << endl;
        i++;
    } while (i <= 5);
    cout << "Finished, i = " << i << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int age;
    do {
        cout << "Enter age (1-120): ";
        cin >> age;
    } while (age < 1 || age > 120);
    cout << "Age accepted: " << age << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int choice;
    do {
        cout << "1. Say Hello  2. Say Bye  3. Exit: ";
        cin >> choice;
        if (choice == 1) {
            cout << "Hello!" << endl;
        } else if (choice == 2) {
            cout << "Bye!" << endl;
        } else if (choice != 3) {
            cout << "Invalid choice" << endl;
        }
    } while (choice != 3);
    cout << "Program ended." << endl;
    return 0;
}

